```java
package com.loanfactory.lfiq.onboarding.facade.impl;

import com.loanfactory.lfiq.onboarding.entity.OnboardingWorkflowEntity;
import com.loanfactory.lfiq.onboarding.facade.OnboardingWorkflowFacade;
import com.loanfactory.lfiq.onboarding.model.request.UpdateOnboardingStateRequest;
import com.loanfactory.lfiq.onboarding.service.OnboardingWorkflowService;
import com.loanfactory.lfiq.utils.SecurityUtils;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class OnboardingWorkflowFacadeImpl implements OnboardingWorkflowFacade {

    private final OnboardingWorkflowService onboardingWorkflowService;

    @Override
    public OnboardingWorkflowEntity getOrCreateForCurrentUser() {
        final String userId = SecurityUtils.getCurrentUserId(true);
        return onboardingWorkflowService.getOrCreateByUserId(userId);
    }

    @Override
    public OnboardingWorkflowEntity updateForCurrentUser(final UpdateOnboardingStateRequest request) {
        final String userId = SecurityUtils.getCurrentUserId(true);
        return onboardingWorkflowService.updateState(userId, request);
    }
}
```

IMPORTANT: Use com.loanfactory.lfiq.utils.SecurityUtils (lfiq-backend local utils), NOT tera-core ServicesUtils. The project has its own SecurityUtils that wraps the authentication context.

SecurityUtils.getCurrentUserId(true) throws an authentication error if no user is logged in (the true parameter means "auth required").

